import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { RouterLink } from '@angular/router';
import { HttpClient } from '@angular/common/http';
import { firstValueFrom } from 'rxjs';
import { AdminService } from '../../core/admin.service';

// Matches API_BASE in core/auth.service.ts — update both if you add environment.ts
const API_BASE = 'http://localhost:3000/api';

interface FieldDef { key: string; label: string; type?: 'text' | 'number' | 'datetime-local' | 'select' | 'checkbox'; options?: string[]; }
interface ResourceDef {
  key: string;           // API path segment
  title: string;
  columns: string[];     // fields shown in table
  fields: FieldDef[];    // fields shown in the add/edit form
}

const RESOURCES: ResourceDef[] = [
  {
    key: 'users', title: 'Users',
    columns: ['id', 'name', 'email', 'phone', 'role'],
    fields: [
      { key: 'name', label: 'Name' },
      { key: 'email', label: 'Email' },
      { key: 'phone', label: 'Phone' },
      { key: 'role', label: 'Role', type: 'select', options: ['member', 'admin'] },
    ],
  },
  {
    key: 'trainers', title: 'Trainers',
    columns: ['id', 'name', 'specialty'],
    fields: [
      { key: 'name', label: 'Name' },
      { key: 'specialty', label: 'Specialty' },
      { key: 'bio', label: 'Bio' },
    ],
  },
  {
    key: 'classes', title: 'Classes',
    columns: ['id', 'name', 'trainer_name', 'location', 'starts_at', 'capacity', 'spots_left'],
    fields: [
      { key: 'name', label: 'Name' },
      { key: 'trainer_id', label: 'Trainer ID', type: 'number' },
      { key: 'category', label: 'Category' },
      { key: 'location', label: 'Location' },
      { key: 'starts_at', label: 'Starts At', type: 'datetime-local' },
      { key: 'ends_at', label: 'Ends At', type: 'datetime-local' },
      { key: 'capacity', label: 'Capacity', type: 'number' },
    ],
  },
  {
    key: 'plans', title: 'Membership Plans',
    columns: ['id', 'name', 'price', 'classes_per_month', 'duration_months', 'is_active'],
    fields: [
      { key: 'name', label: 'Name' },
      { key: 'price', label: 'Price', type: 'number' },
      { key: 'classes_per_month', label: 'Classes/Month (blank=unlimited)', type: 'number' },
      { key: 'duration_months', label: 'Duration (months)', type: 'number' },
      { key: 'is_active', label: 'Active', type: 'checkbox' },
    ],
  },
  {
    key: 'memberships', title: 'Memberships',
    columns: ['id', 'user_name', 'plan_name', 'status', 'classes_used_this_month', 'renews_at'],
    fields: [
      { key: 'status', label: 'Status', type: 'select', options: ['active', 'expired', 'cancelled'] },
      { key: 'plan_id', label: 'Plan ID', type: 'number' },
      { key: 'renews_at', label: 'Renews At', type: 'datetime-local' },
    ],
  },
  {
    key: 'bookings', title: 'Bookings',
    columns: ['id', 'user_name', 'class_name', 'starts_at', 'status'],
    fields: [
      { key: 'status', label: 'Status', type: 'select', options: ['booked', 'cancelled', 'attended', 'no_show'] },
    ],
  },
];

@Component({
  selector: 'app-admin',
  standalone: true,
  imports: [CommonModule, FormsModule, RouterLink],
  templateUrl: './admin.component.html',
  styleUrl: './admin.component.css',
})
export class AdminComponent implements OnInit {
  resources = RESOURCES;
  active: ResourceDef = RESOURCES[0];
  rows: any[] = [];
  loading = false;
  error = '';

  showForm = false;
  editingId: number | null = null;
  formModel: any = {};

  stats: any = null;

  // CHANGED — pending-account approvals
  activeSection: 'resource' | 'approvals' = 'resource';
  pendingApprovals: any[] = [];
  approvalsLoading = false;

  constructor(private admin: AdminService, private http: HttpClient) {}

  async ngOnInit() {
    this.stats = await this.admin.stats().catch(() => null);
    await this.select(this.resources[0]);
  }

  async select(res: ResourceDef) {
    this.activeSection = 'resource'; // CHANGED
    this.active = res;
    this.showForm = false;
    this.error = '';
    this.loading = true;
    try {
      this.rows = await this.admin.list(res.key);
    } catch (e: any) {
      this.error = e?.error?.error || 'Failed to load data';
      this.rows = [];
    } finally {
      this.loading = false;
    }
  }

  openCreate() {
    this.editingId = null;
    this.formModel = {};
    this.showForm = true;
  }

  openEdit(row: any) {
    this.editingId = row.id;
    this.formModel = { ...row };
    this.showForm = true;
  }

  cancelForm() {
    this.showForm = false;
    this.editingId = null;
  }

  async save() {
    try {
      if (this.editingId) {
        await this.admin.update(this.active.key, this.editingId, this.formModel);
      } else {
        await this.admin.create(this.active.key, this.formModel);
      }
      this.showForm = false;
      await this.select(this.active);
    } catch (e: any) {
      this.error = e?.error?.error || 'Save failed';
    }
  }

  async remove(row: any) {
    if (!confirm(`Delete this ${this.active.title.slice(0, -1)}?`)) return;
    try {
      await this.admin.remove(this.active.key, row.id);
      await this.select(this.active);
    } catch (e: any) {
      this.error = e?.error?.error || 'Delete failed';
    }
  }

  // CHANGED — pending-account approvals
  async showApprovals() {
    this.activeSection = 'approvals';
    this.showForm = false;
    this.error = '';
    this.approvalsLoading = true;
    try {
      this.pendingApprovals = await firstValueFrom(
        this.http.get<any[]>(`${API_BASE}/admin/pending-approvals`)
      );
    } catch (e: any) {
      this.error = e?.error?.error || 'Failed to load pending approvals';
      this.pendingApprovals = [];
    } finally {
      this.approvalsLoading = false;
    }
  }

  async approveUser(row: any) {
    try {
      await firstValueFrom(this.http.post(`${API_BASE}/admin/users/${row.id}/approve`, {}));
      await this.showApprovals();
    } catch (e: any) {
      this.error = e?.error?.error || 'Approval failed';
    }
  }

  async rejectUser(row: any) {
    if (!confirm(`Reject ${row.name}'s account request?`)) return;
    try {
      await firstValueFrom(this.http.post(`${API_BASE}/admin/users/${row.id}/reject`, {}));
      await this.showApprovals();
    } catch (e: any) {
      this.error = e?.error?.error || 'Rejection failed';
    }
  }
}
<div class="adm-shell">
  <aside class="adm-nav">
    <h2>Admin</h2>
    <a routerLink="/app" class="adm-back-link">← Back to app</a>
    <nav>
      <button *ngFor="let r of resources" class="adm-nav-btn"
              [class.adm-active]="r.key === active.key && activeSection === 'resource'"
              (click)="select(r)">{{ r.title }}</button>
      <button class="adm-nav-btn" [class.adm-active]="activeSection === 'approvals'"
              (click)="showApprovals()">Approvals</button>
    </nav>
    <div class="adm-stats" *ngIf="stats">
      <div>Users: {{ stats.users }}</div>
      <div>Trainers: {{ stats.trainers }}</div>
      <div>Upcoming classes: {{ stats.upcoming_classes }}</div>
      <div>Active memberships: {{ stats.active_memberships }}</div>
      <div>Bookings today: {{ stats.bookings_today }}</div>
    </div>
  </aside>

  <main class="adm-main">
    <div class="adm-header" *ngIf="activeSection === 'resource'">
      <h1>{{ active.title }}</h1>
      <button class="adm-btn-primary" (click)="openCreate()">+ Add</button>
    </div>

    <p class="adm-error" *ngIf="error">{{ error }}</p>

    <ng-container *ngIf="activeSection === 'resource'">
      <p *ngIf="loading">Loading…</p>

      <table class="adm-table" *ngIf="!loading && rows.length">
        <thead>
          <tr>
            <th *ngFor="let c of active.columns">{{ c }}</th>
            <th></th>
          </tr>
        </thead>
        <tbody>
          <tr *ngFor="let row of rows">
            <td *ngFor="let c of active.columns">{{ row[c] }}</td>
            <td class="adm-row-actions">
              <button (click)="openEdit(row)">Edit</button>
              <button class="adm-btn-danger" (click)="remove(row)">Delete</button>
            </td>
          </tr>
        </tbody>
      </table>

      <p *ngIf="!loading && !rows.length">No records.</p>
    </ng-container>

    <!-- CHANGED: pending-account approvals -->
    <ng-container *ngIf="activeSection === 'approvals'">
      <div class="adm-header"><h1>Pending Approvals</h1></div>
      <p *ngIf="approvalsLoading">Loading…</p>

      <table class="adm-table" *ngIf="!approvalsLoading && pendingApprovals.length">
        <thead>
          <tr>
            <th>Name</th><th>Email</th><th>Phone</th><th>Category</th><th>Plan</th><th>Price</th><th>Requested</th><th></th>
          </tr>
        </thead>
        <tbody>
          <tr *ngFor="let row of pendingApprovals">
            <td>{{ row.name }}</td>
            <td>{{ row.email }}</td>
            <td>{{ row.phone }}</td>
            <td>{{ row.preferred_category }}</td>
            <td>{{ row.plan_name }} ({{ row.duration_months }} mo)</td>
            <td>{{ row.price }} TND</td>
            <td>{{ row.requested_at | date:'short' }}</td>
            <td class="adm-row-actions">
              <button class="adm-btn-success" (click)="approveUser(row)">Approve</button>
              <button class="adm-btn-danger" (click)="rejectUser(row)">Reject</button>
            </td>
          </tr>
        </tbody>
      </table>

      <p *ngIf="!approvalsLoading && !pendingApprovals.length">No pending requests.</p>
    </ng-container>
  </main>

  <div class="adm-modal-backdrop" *ngIf="showForm" (click)="cancelForm()">
    <div class="adm-modal" (click)="$event.stopPropagation()">
      <h3>{{ editingId ? 'Edit' : 'Add' }} {{ active.title.slice(0, -1) }}</h3>
      <form (ngSubmit)="save()">
        <label *ngFor="let f of active.fields">
          {{ f.label }}
          <select *ngIf="f.type === 'select'" [(ngModel)]="formModel[f.key]" [name]="f.key">
            <option *ngFor="let o of f.options" [value]="o">{{ o }}</option>
          </select>
          <input *ngIf="f.type === 'checkbox'" type="checkbox" [(ngModel)]="formModel[f.key]" [name]="f.key" />
          <input *ngIf="!f.type || (f.type !== 'select' && f.type !== 'checkbox')"
                 [type]="f.type || 'text'" [(ngModel)]="formModel[f.key]" [name]="f.key" />
        </label>
        <div class="adm-modal-actions">
          <button type="button" class="adm-btn-secondary" (click)="cancelForm()">Cancel</button>
          <button type="submit" class="adm-btn-primary">Save</button>
        </div>
      </form>
    </div>
  </div>
</div>
